time = 0

# Continue until no more swaps happen
while True:
    # Find all positions where an 'M' is immediately followed by an 'F'
    swaps = []
    for i in range(len(line) - 1):
        if line[i] == 'M' and line[i+1] == 'F':
            swaps.append(i)

    if not swaps:
        break

    # Process swaps in reverse order to avoid affecting subsequent swaps
    for i in reversed(swaps):
        line[i], line[i+1] = line[i+1], line[i]

    time += 1

print(time)
