    a, b, c = map(int, input().split())
    s = input()

    # We need to win at least ceil(n/2) games
    wins_needed = (n + 1) // 2  # ceil(n/2)

    # Try to construct Alice's sequence
    alice_seq = []
    wins = 0

    for move in s:
        if move == 'R':
            # Bob plays rock, Alice can win with paper
            if b > 0:
                alice_seq.append('P')
                b -= 1
                wins += 1
            else:
                # No paper left, try to tie or lose
                if a > 0:
                    alice_seq.append('R')  # tie with rock
                    a -= 1
                else:
                    alice_seq.append('S')  # lose with scissors
                    c -= 1
        elif move == 'P':
            # Bob plays paper, Alice can win with scissors
            if c > 0:
                alice_seq.append('S')
                c -= 1
                wins += 1
            else:
                # No scissors left, try to tie or lose
                if a > 0:
                    alice_seq.append('R')  # tie with rock
                    a -= 1
                else:
                    alice_seq.append('P')  # lose with paper
                    b -= 1
        elif move == 'S':
            # Bob plays scissors, Alice can win with rock
            if a > 0:
                alice_seq.append('R')
                a -= 1
                wins += 1
