n, k, m, t = map(int, input().split())

for _ in range(t):
    op, pos = map(int, input().split())

    if op == 0:
        # Break link at position pos
        # Left part: length pos, right part: length n - pos
        if k <= pos:
            # Doctor is in left part, right part disappears
            pass  # k remains the same
        else:
            # Doctor is in right part, left part disappears
            k -= pos  # New position in right part

        # Update length
        if k <= pos:
            n = pos  # Right part disappears
        else:
            n = n - pos  # Left part disappears

    elif op == 1:
        # Insert at position pos
        # All positions ≥ pos shift right by 1
        if k >= pos:
            k += 1
        n += 1

    print(n, k)
"}

