import math

# Read input
def read_input():
    data = input().strip().split()
    if not data:
        return None
    return data

# Read n, m, k
input_data = []
while True:
    line = read_input()
    if line is None:
        break
    input_data.extend(line)

if not input_data:
    n = 0
    m = 0
    k = 0.0
else:
    n = int(input_data[0])
    m = int(input_data[1])
    k = float(input_data[2])

# Read current skills
current_skills = {}
for _ in range(n):
    line = read_input()
    if not line:
        continue
    name, exp = line[0], int(line[1])
current_skills[name] = exp

# Read class-specific skills
class_skills = set()
for _ in range(m):
    line = read_input()
    if not line:
        continue
    class_skills.add(line[0])

# Process skills after transmigration
result = {}

# Process current skills
for name, exp in current_skills.items():
    new_exp = int(math.floor(k * exp))
    if new_exp >= 100:
        result[name] = new_exp

# Add class-specific skills
for name in class_skills:
    if name not in result:
        result[name] = 0

# Sort lexicographically
sorted_skills = sorted(result.items())

# Output
print(len(sorted_skills))
for name, exp in sorted_skills:
    print(f"{name} {exp}")
"}

