def is_triangular(x):
    """Check if x is a triangular number."""
    if x == 0:
        return False  # 0 is not considered
    # Check if 8x + 1 is a perfect square
    s = int((8 * x + 1) ** 0.5)
    return s * s == 8 * x + 1

def solve(n):
    # Check all possible first triangular numbers
    found = False
    for k in range(1, int((2 * n) ** 0.5) + 2):
        t1 = k * (k + 1) // 2
        if t1 > n:
            break
        remainder = n - t1
        if remainder < 0:
            continue
        if is_triangular(remainder):
            found = True
            break
    return "YES" if found else "NO"

# Test with n = 719805256
print(solve(719805256))
