    return (8 * x + 1) ** 0.5 == int((8 * x + 1) ** 0.5)

def solve(n):
    # Check all possible pairs of triangular numbers
    # t1 + t2 = n, where t1 = k1*(k1+1)/2, t2 = k2*(k2+1)/2
    found = False
    for k1 in range(1, int((2 * n) ** 0.5) + 2):
        t1 = k1 * (k1 + 1) // 2
        if t1 > n:
            break
        for k2 in range(1, int((2 * n) ** 0.5) + 2):
            t2 = k2 * (k2 + 1) // 2
            if t1 + t2 == n:
                found = True
                break
            elif t1 + t2 > n:
                break
    return "YES" if found else "NO"

n = int(input())
print(solve(n))
