def solve():
    n, m, k = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(input().strip()))

    # Find any empty cell to start from
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                start = (i, j)
                break
        if start:
            break

    # BFS to visit all empty cells
    from collections import deque

    visited = set()
    queue = deque([start])
    visited.add(start)

    order = []  # Store order of visit

    while queue:
        i, j = queue.popleft()
        order.append((i, j))

        # Visit neighbors
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.' and (ni, nj) not in visited:
                visited.add((ni, nj))
                queue.append((ni, nj))

    # We need to keep (len(order) - k) empty cells
    # Mark all empty cells as walls, then unmark the first (len(order) - k) cells
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                grid[i][j] = 'X'

    # Keep the first (len(order) - k) empty cells
    for i, j in order[:len(order) - k]:
        grid[i][j] = '.'

    # Print result
    for row in grid:
        print(''.join(row))

solve()
