def find_farthest(start, tree, n):
    """Find the farthest vertex from start and its distance"""
    max_dist = 0
    farthest_vertex = start
    visited = [False] * (n + 1)
    stack = [(start, 0)]

    while stack:
        vertex, dist = stack.pop()
        if visited[vertex]:
            continue
        visited[vertex] = True
        if dist > max_dist:
            max_dist = dist
            farthest_vertex = vertex
        for neighbor in tree[vertex]:
            stack.append((neighbor, dist + 1))

    return farthest_vertex, max_dist

def find_diameter(tree, n):
    """Find the diameter of the tree"""
    start = 1
    farthest_vertex, _ = find_farthest(start, tree, n)
    end, _ = find_farthest(farthest_vertex, tree, n)
    return farthest_vertex, end

def solve():
    n = int(input())
    tree = [[] for _ in range(n + 1)]

    for _ in range(n - 1):
        a, b = map(int, input().split())
        tree[a].append(b)
        tree[b].append(a)

    # Find diameter
    a, b = find_diameter(tree, n)

    # Find farthest from a that is not a or b
    farthest_c = -1
    max_dist_c = 0

    visited = [False] * (n + 1)
    stack = [(a, 0)]

    while stack:
        vertex, dist = stack.pop()
        if visited[vertex]:
            continue
        visited[vertex] = True

        if vertex != a and vertex != b and dist > max_dist_c:
            max_dist_c = dist
            farthest_c = vertex

        for neighbor in tree[vertex]:
            stack.append((neighbor, dist + 1))

    # Now calculate how many edges are covered
    # Edge list
    edges = set()
    for i in range(1, n + 1):
        for j in tree[i]:
            if i < j:
                edges.add((i, j))

    # Check which edges are covered by at least one path
    covered = set()

    # Helper: check if edge is on the path from u to v
    def edge_on_path(u, v, edge, tree):
        """Check if edge is on the path from u to v"""
        def is_on_path(x, y, z, tree):
            # Check if x is on the path from y to z
            visited = [False] * (n + 1)
            stack = [y]
            visited[y] = True

            while stack:
                current = stack.pop()
                if current == z:
                    return True
                for neighbor in tree[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            return False

        u1, u2 = edge
        return is_on_path(u, u1, u2, tree) or is_on_path(u, u2, u1, tree)

    for edge in edges:
        if edge_on_path(a, b, edge, tree) or edge_on_path(a, farthest_c, edge, tree) or edge_on_path(b, farthest_c, edge, tree):
            covered.add(edge)

