def solve():
    n = int(input())

    # Build the tree using adjacency list
    from collections import defaultdict
    tree = defaultdict(list)

    for _ in range(n - 1):
        u, v = map(int, input().split())
        tree[u].append(v)
        tree[v].append(u)

    # We need to find the size of each subtree and compute the expected steps
    # The expected steps is the sum of 1 / size_of_subtree(v) for all nodes v

    # Compute subtree sizes using DFS
    def dfs(node, parent):
        size = 1
        for neighbor in tree[node]:
            if neighbor != parent:
                size += dfs(neighbor, node)
        return size

    # Compute sizes for all nodes (assuming root is 1)
    sizes = {1: dfs(1, -1)}

    # For each node, compute its size (this just propagates the size from root)
    # But we need sizes for all nodes, not just the root
    # Actually, we can just compute sizes recursively

    # Let's do a second DFS to collect sizes for all nodes
    def compute_sizes(node, parent):
        if node not in sizes:
            sizes[node] = 1
            for neighbor in tree[node]:
                if neighbor != parent:
                    compute_sizes(neighbor, node)
                    sizes[node] += sizes[neighbor]

    compute_sizes(1, -1)

    # Calculate expected steps
    expected = 0.0
    for node in sizes:
        expected += 1.0 / sizes[node]

    print(expected)

