def solve():
    n = int(input())

    # Build the tree using adjacency list
    from collections import defaultdict
    tree = defaultdict(list)

    for _ in range(n - 1):
        u, v = map(int, input().split())
        tree[u].append(v)
        tree[v].append(u)

    # Compute subtree sizes using DFS
    def dfs(node, parent):
        size = 1
        for neighbor in tree[node]:
            if neighbor != parent:
                size += dfs(neighbor, node)
        return size

    # Compute sizes for all nodes (assuming root is 1)
    sizes = {1: dfs(1, -1)}

    # For each node, compute its size
    def compute_sizes(node, parent):
        if node not in sizes:
            sizes[node] = 1
            for neighbor in tree[node]:
                if neighbor != parent:
                    compute_sizes(neighbor, node)
                    sizes[node] += sizes[neighbor]
        return sizes[node]

    compute_sizes(1, -1)

    # Verify all sizes are computed
    for node in tree:
        if node not in sizes:
            pass  # Or raise an error

    # Calculate expected steps recursively
    def expected_steps(node, parent):
        size = sizes[node]
        if size == 1:
            return 1.0

        total = 1.0
        for child in tree[node]:
            if child != parent:
                # Probability of removing from child's subtree
                p = sizes[child] / size
                # Expected steps after removing from child's subtree
                # = 1 + expected_steps for the remaining nodes
                # (the child's subtree is removed, we need to remove the rest)
                total += p * (1.0 + expected_steps(node, child))

        return total

    result = expected_steps(1, -1)
    print(result)

