import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    s = int(data[1])
    edges = [[] for _ in range(n + 1)]
    idx = 2

    for i in range(n - 1):
        a = int(data[idx])
        b = int(data[idx + 1])
        edges[a].append(b)
        edges[b].append(a)
        idx += 2

    # Compute distances from each vertex
    distances = []
    for start in range(1, n + 1):
        dist = [-1] * (n + 1)
        q = deque([start])
        dist[start] = 0

        while q:
            u = q.popleft()
            for v in edges[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        distances.append(dist)

    # Find maximum distance
    max_distance = 0
    for dist in distances:
        max_distance = max(max_distance, max(dist[1:]))

    # Check if it's a star tree (all edges incident to a common vertex)
    degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in edges[u]:
            degree[u] += 1

    center_degree = max(degree)

    # If it's a star tree (center_degree == n-1), answer is s/2
    if center_degree == n - 1:
        print(s / 2.0)
    elif max_distance == 1:
        print(s / (n - 2) if n > 3 else s)
    else:
        print(s / (max_distance - 1))

if __name__ == "__main__":
