import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    index = 1

    # Containers: stack, queue, deck
    stack = []
    queue = []
    deck = []

    for i in range(n):
        command = data[index]
        index += 1

        if command == '1':
            # Add command
            value = int(data[index])
            index += 1

            # Add to the first non-empty container
            if stack:
                stack.append(value)
            elif queue:
                queue.append(value)
            else:
                deck.append(value)

            # Print the action
            if stack:
                print("pushStack")
            elif queue:
                print("pushQueue")
            else:
                print("pushFront")
        else:  # command == '0'
            # Extract command
            # Extract from containers in decreasing order of their values

            # Collect all values and their container type
            values = []
            if stack:
                values.append((stack[-1], 'stack'))
            if queue:
                values.append((queue[-1], 'queue'))
            if deck:
                values.append((deck[-1], 'deck'))

            if not values:
                print(0)
            else:
                # Sort by value (descending) and then by container type (pop order)
                values.sort(key=lambda x: (-x[0], x[1]))

                k = len(values)
                print(k, end=' ')
                for val, container in values:
                    if container == 'stack':
                        print("popStack", end=' ')
                    elif container == 'queue':
                        print("popQueue", end=' ')
                    else:  # deck
                        print("popFront", end=' ')
                print()

solve()
