import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    c = []
    for i in range(n):
        row = list(map(int, sys.stdin.readline().split()))
        c.append(row)

    min_total = float('inf')
    best_point = (0, 0)

    for li in range(n + 1):
        for lj in range(m + 1):
            total = 0
            for i in range(n):
                for j in range(m):
                    # Calculate distance squared from (li, lj) to (i, j)
                    # Distance squared = 16 * ((li - i)^2 + (lj - j)^2)
                    # But we multiply by 9/8 to get the actual time
                    # Total time = 18 * c[i][j] * ((li - i)^2 + (lj - j)^2)
                    dist_sq = (li - i) ** 2 + (lj - j) ** 2
                    total += c[i][j] * dist_sq

            total = total * 18

            if total < min_total:
                min_total = total
                best_point = (li, lj)

    print(min_total)
    print(best_point[0], best_point[1])

if __name__ == "__main__":
    solve()
"}

