def solve():
    n, k = map(int, input().split())
    x = list(map(int, input().split()))

    # Set of guessed cells
    S = set(x)

    # Count valid scenarios (a, b)
    valid = 0

    # Case 1: a == b
    for a in range(1, n + 1):
        if a not in S:
            valid += 1

    # Case 2: a != b, |a - b| = 1
    # For each adjacent pair (a, b), check if there exists a split
    # where a avoids the first part and b avoids the second part
    # We can just check if a and b are not in S
    for a in range(1, n + 1):
        if a not in S:
            if 1 <= a - 1 <= n:
                valid += 1
            if 2 <= a + 1 <= n:
                valid += 1

    print(valid)

solve()
