    # Make each row have duplicates
    for i in range(9):
        row = grid[i]
        if len(set(row)) == 9:
            # Change last element to match first
            grid[i][8] = row[0]

    # Make each column have duplicates
    for j in range(9):
        col = [grid[i][j] for i in range(9)]
        if len(set(col)) == 9:
            # Change last element to match first
            grid[8][j] = col[0]

    # Make each 3x3 block have duplicates
    for block_row in range(3):
        for block_col in range(3):
            # Extract the 3x3 block
            block = []
            for i in range(3 * block_row, 3 * block_row + 3):
                for j in range(3 * block_col, 3 * block_col + 3):
                    block.append(grid[i][j])

            if len(set(block)) == 9:
                # Change last element to match first
                # Find the position of the last element in the block
                # We'll change the last element in row-major order
                for i in range(3 * block_row, 3 * block_row + 3):
                    for j in range(3 * block_col, 3 * block_col + 3):
                        if i == 3 * block_row + 2 and j == 3 * block_col + 2:
                            grid[i][j] = block[0]
                            break
                        if i > 3 * block_row + 2 or (i == 3 * block_row + 2 and j > 3 * block_col + 2):
                            break

    return grid

