def simulate_fireworks(n, times):
    queue = [(0, 0, (0, 1), 1)]  # (x, y, direction, level)
    visited = set()

    while queue:
        x, y, dir_vec, level = queue.pop(0)

        time = times[level - 1]

        for _ in range(time):
            visited.add((x, y))
            x += dir_vec[0]
            y += dir_vec[1]

        if level < n:
            # Try different rotation: (dx+1, dy) and (dx, dy+1)
            for dx, dy in [(dir_vec[0] + 1, dir_vec[1]), (dir_vec[0], dir_vec[1] + 1)]:
                queue.append((x, y, (dx, dy), level + 1))

    return len(visited)

