def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        a = list(map(int, input().split()))

        # Convert each box to its power of two exponent
        power_count = [0] * 60  # Since 2^60 > 10^18
        for size in a:
            power = size.bit_length() - 1
            power_count[power] += 1

        # Calculate the binary representation of n
        need = [0] * 60
        for i in range(60):
            need[i] = (n >> i) & 1

        # Try to fill from highest power to lowest
        answer = 0
        for i in range(59, -1, -1):
            # If we need this power and we have it, no action needed
            if need[i] == 0:
                continue

            # If we have boxes at this power
            if power_count[i] > 0:
                power_count[i] -= 1
                power_count[i + 1] += 2  # Divide this box into two smaller ones
                answer += 1

        # After processing, check if we could fill the bag
        filled = True
        for i in range(60):
            if need[i] == 1 and power_count[i] == 0:
                filled = False
                break

        if filled:
            print(answer)
        else:
            print(-1)

