def count_with_parity(x, parity):
    """Count numbers from 0 to x with Hamming weight parity `parity` (0 = even, 1 = odd)."""
    s = bin(x)[2:]
    n = len(s)

    # DP[i][tight][p] = number of ways to fill first i bits
    # tight = 1 if we're still constrained by x's bits, 0 otherwise
    # p = current parity of Hamming weight

    # Initialize DP
    dp = [[[0, 0] for _ in range(n + 1)] for _ in range(2)]
    dp[0][0][0] = 1

    for i in range(n):
        for tight in [0, 1]:
            for p in [0, 1]:
                if dp[tight][i][p] == 0:
                    continue

                for bit in [0, 1]:
                    new_tight = tight and (bit == int(s[i]))
                    new_p = (p + bit) % 2
                    dp[new_tight][i + 1][new_p] += dp[tight][i][p]

    return dp[0][n][parity] + dp[1][n][parity]

