def solve():
    n, m, k = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(input().strip()))

    # Find all empty cells and build adjacency list
    empty_cells = []
    adj = {}

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_cells.append((i, j))
                adj[(i, j)] = []

                # Check neighbors
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.':
                        adj[(i, j)].append((ni, nj))

    # Build BFS spanning tree
    if not empty_cells:
        return

    start = empty_cells[0]
    parent = {}
    visited = set()
    queue = [start]
    visited.add(start)
    parent[start] = None

    while queue:
        curr = queue.pop(0)
        for neighbor in adj[curr]:
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = curr
                queue.append(neighbor)

    # Find leaves (degree 1)
    leaves = []
    for cell in empty_cells:
        if len(adj[cell]) == 1:
            leaves.append(cell)

    # Remove k cells from leaves (preferably from the end)
    for i in range(k):
        if leaves:
            cell = leaves[-1]
            grid[cell[0]][cell[1]] = 'X'
            leaves.pop()

