s = input().strip()
k = int(input())

# Parse forbidden pairs
forbidden_pairs = set()
for _ in range(k):
    pair = input().strip()
    forbidden_pairs.add((pair[0], pair[1]))
    forbidden_pairs.add((pair[1], pair[0]))

# Dynamic programming approach
# dp[i] = {last_char: min_removals}
dp = {None: 0}

for char in s:
    new_dp = {}
    for last_char, removals in dp.items():
        # Option 1: Remove current character
        if last_char in new_dp:
            new_dp[last_char] = min(new_dp[last_char], removals)
        else:
            new_dp[last_char] = removals

        # Option 2: Keep current character (if allowed)
        if last_char is None or (last_char, char) not in forbidden_pairs:
            if char in new_dp:
                new_dp[char] = min(new_dp[char], removals)
            else:
                new_dp[char] = removals

    dp = new_dp

# Find minimum removals
print(min(dp.values()))
