    """Make the Sudoku grid anti-Sudoku by changing at most 9 elements"""
    # Check each row
    for i in range(9):
        if len(set(grid[i])) == 9:
            # Change last element to match first
            grid[i] = grid[i][:8] + grid[i][0]

    # Check each column
    for j in range(9):
        col = [grid[i][j] for i in range(9)]
        if len(set(col)) == 9:
            # Change last element to match first
            grid[8][j] = col[0]

