import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Create a copy to work with
    work = arr[:]
    swaps = []

    # Find what element should be at each position
    sorted_arr = sorted(arr)

    # Create a lookup table for each element's positions
    pos = {}
    for i in range(n):
        if work[i] not in pos:
            pos[work[i]] = []
        pos[work[i]].append(i)

    # For each position, find where the correct element is located
    for i in range(n):
        target = sorted_arr[i]

        # Find the correct position for this target
        if len(pos[target]) > 1:
            # Handle duplicates by finding the first occurrence after i
            target_idx = -1
            for j in range(n):
                if work[j] == target and j > i:
                    target_idx = j
                    break

            if target_idx == -1:
