import sys

def count_bits(x):
    """Return the number of bits set to 1 in x"""
    return x.bit_count()

def solve_query(l, r):
    """Find x in [l, r] with maximum number of '1' bits, smallest x if tie"""
    max_bits = r.bit_length()

    # Ideal number with max_bits bits all set
    ideal = (1 << max_bits) - 1

    if ideal >= l:
        return ideal
    else:
        # Can't fit the ideal, so return the largest number with max_bits-1 bits
        return (1 << (max_bits - 1)) - 1


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    out = []

    idx = 1
    for _ in range(n):
        l = int(data[idx])
        r = int(data[idx + 1])
        idx += 2

        answer = solve_query(l, r)
        out.append(str(answer))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
