    n, m, k = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(input().strip()))

    # Find all empty cells and perform DFS
    from collections import deque
    visited = [[False] * m for _ in range(n)]
    q = deque()

    # Find starting cell
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                start = (i, j)
                visited[i][j] = True
                q.append((i, j))
                break
        if start:
            break

    # DFS to visit all empty cells
    order = []
    while q:
        i, j = q.pop()  # DFS - use pop() instead of popleft()
        order.append((i, j))
        for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and not visited[ni][nj] and grid[ni][nj] == '.':
                visited[ni][nj] = True
                q.append((ni, nj))

    # Mark last k cells as walls
    for i in range(len(order) - 1, len(order) - k - 1, -1):
        ci, cj = order[i]
        grid[ci][cj] = 'X'

    # Print result
    for row in grid:
        print(''.join(row))

