    count = {}
    for box in boxes:
        power = box.bit_length() - 1  # Get the exponent of the power of two
        count[power] = count.get(power, 0) + 1
    return count

def solve():
    t = int(input())

    for _ in range(t):
        n, m = map(int, input().split())
        boxes = list(map(int, input().split()))

        # Count how many boxes we have of each power of two
        count = count_powers_of_two(boxes)

        # We need to fill a bag of size n
        # Check if we have at least one box of each power of two that appears in n's binary representation
        needed = {}
        remaining = n

        power = n.bit_length() - 1
        while power >= 0:
            # Check if this power is needed
            if remaining & (1 << power):
                needed[power] = 1
                remaining ^= (1 << power)
            power -= 1

        # Try to satisfy the needs
        result = 0

        for power in sorted(needed.keys(), reverse=True):
            if count.get(power, 0) >= needed[power]:
                # We have enough of this power
                count[power] -= needed[power]
            else:
                # We need to get more by dividing larger boxes
                needed_boxes = needed[power] - count.get(power, 0)

                # Find boxes larger than this power to divide
                found = False
                for p in range(power + 1, n.bit_length() + 1):
                    if count.get(p, 0) > 0:
                        # Divide this box to get boxes of power 'power'
                        # Each division of a box of size 2^p gives 2 boxes of size 2^(p-1)
                        # So to get one box of size 2^power from a box of size 2^p, we need p - power divisions
                        count[p] -= 1
                        count[power] = count.get(power, 0) + 1
                        result += p - power
                        needed_boxes -= 1
                        found = True

                        if needed_boxes == 0:
                            break

                if not found:
                    # Not enough boxes to satisfy needs
                    print(-1)
                    break
        else:
            print(result)

