# Check if impossible
if a + b > n or (a == n and b == n):
    print("NO")
else:
    # Construct the adjacency matrix
    matrix = [[0] * n for _ in range(n)]

    # First (a-1) vertices form a complete component
    # All vertices in this component are connected to each other
    for i in range(a-1):
        for j in range(i+1, a-1):
            matrix[i][j] = 1
            matrix[j][i] = 1

    # Remaining vertices are isolated in the graph
    # They should be connected to all vertices in the complete component in the complement
    for i in range(a-1, n):
        for j in range(a-1):
            matrix[i][j] = 1
            matrix[j][i] = 1

    # Output the result
    print("YES")
    for row in matrix:
        print("".join(map(str, row)))
