def solve():
    n = int(input())
    if n == 0:
        return

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    # Compute subtree sizes using DFS
    def dfs(u, parent):
        size = 1
        for v in adj[u]:
            if v != parent:
                size += dfs(v, u)
        return size

    # Mark visited and compute sizes
    visited = [False] * (n + 1)
    sizes = [0] * (n + 1)

    def dfs_mark(u, parent):
        sizes[u] = 1
        visited[u] = True
        for v in adj[u]:
            if not visited[v] and v != parent:
                dfs_mark(v, u)
                sizes[u] += sizes[v]
        return

    dfs_mark(1, -1)

    # Calculate expected steps
    expected = 0.0
    for i in range(1, n + 1):
        expected += 1.0 / sizes[i]
    expected -= 1.0 / n

    print(f"{expected:.10f}")

if __name__ == "__main__":
    solve()
