        pair = input().strip()
        forbidden.add((pair[0], pair[1]))
        forbidden.add((pair[1], pair[0]))

    # Brute-force: try all possible subsets
    n = len(s)
    min_removals = n  # worst case: remove all

    for mask in range(1 << n):
        # Check if this subset is valid
        valid = True
        for i in range(n):
            if mask & (1 << i):
                # If this character is kept, check its neighbors in the original string
                # But we need to check neighbors in the kept sequence
                # Actually we need to check adjacent characters in the kept sequence
                # Let's build the sequence
                kept_chars = []
                for j in range(n):
                    if mask & (1 << j):
                        kept_chars.append(s[j])
                # Check adjacent pairs
                for j in range(len(kept_chars) - 1):
                    if (kept_chars[j], kept_chars[j+1]) in forbidden:
                        valid = False
                        break
                if not valid:
                    break
        if valid:
            # Count kept characters
            kept = bin(mask).count('1')
            min_removals = min(min_removals, n - kept)

    print(min_removals)

solve()
