def solve():
    s = input().strip()
    k = int(input())
    forbidden = set()
    for _ in range(k):
        pair = input().strip()
        forbidden.add((pair[0], pair[1]))
        forbidden.add((pair[1], pair[0]))

    n = len(s)

    # DP: dp[i][last_char] = min removals to process first i chars
    # We'll use a dictionary for efficiency
    dp = {chr(ord('a') + i): float('inf') for i in range(26)}
    dp[s[0]] = 0

    for i in range(1, n):
        new_dp = {}
        current_char = s[i]

        # Option 1: remove current character
        for last_char, cost in dp.items():
            new_dp[last_char] = min(new_dp.get(last_char, float('inf')), cost + 1)

        # Option 2: keep current character
        for last_char, cost in dp.items():
            if (last_char, current_char) not in forbidden:
                new_dp[current_char] = min(new_dp.get(current_char, float('inf')), cost)

        # Also consider removing the current character from the start
        new_dp[current_char] = min(new_dp.get(current_char, float('inf')), 1)

        dp = new_dp

    print(min(dp.values()))

solve()
