    for j in range(1, n + 1):
        if up[i-1][j] != -1:
            up[i][j] = up[i-1][up[i-1][j]]

# LCA function
def lca(a, b):
    if up[0][a] == -1:
        return a

    # Make a the deeper node
    if up[0][a] == -1:
        return b

    # Equal depth
    if a == b:
        return a

    # Bring them to same depth
    for i in range(LOG-1, -1, -1):
        if up[i][a] != -1 and up[i][a] != up[i][b]:
            a = up[i][a]
            b = up[i][b]

    return up[0][a]

# For each path, count edges
