    a, b = map(int, input().split())
    lca_node = lca(a, b)

    # Count edges from a to LCA
    while a != lca_node:
        # Find edge index
        for u, v, idx in edges:
            if (u == a and v == up[0][a]) or (u == up[0][a] and v == a):
