import sys

def solve(grid):
    """
    Create an anti-sudoku from the given Sudoku grid.
    """
    # Create a copy of the grid
    new_grid = [row[:] for row in grid]

    # For each row, if it has no duplicates, change one element to create duplicates
    for i in range(9):
        if len(set(new_grid[i])) == 9:
            # Find the first element to change
            for j in range(9):
                # Change this element to match the first element in the row
                new_grid[i][j] = new_grid[i][0]
                break

    # For each column, if it has no duplicates, change one element to create duplicates
    for j in range(9):
        if len(set(new_grid[i][j] for i in range(9))) == 9:
            # Find the first element to change
            for i in range(9):
                # Change this element to match the first element in the column
                new_grid[i][j] = new_grid[0][j]
                break

    # For each 3x3 block, if it has no duplicates, change one element to create duplicates
    for block_row in range(3):
        for block_col in range(3):
            # Extract the block
            block = []
            for i in range(3 * block_row, 3 * block_row + 3):
                for j in range(3 * block_col, 3 * block_col + 3):
                    block.append(new_grid[i][j])

            if len(set(block)) == 9:
                # Find the first element to change
                for i in range(3 * block_row, 3 * block_row + 3):
                    for j in range(3 * block_col, 3 * block_col + 3):
                        # Change this element to match the first element in the block
                        new_grid[i][j] = block[0]
                        break
                break

    return new_grid


def main():
    data = sys.stdin.read().strip().split()
    idx = 0

    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        grid = []
        for i in range(9):
            row = data[idx:idx+9]
            idx += 9
            grid.append([int(c) for c in row])

        result = solve(grid)

        for row in result:
            results.append(''.join(str(c) for c in row))

    sys.stdout.write('\n'.join(results))

if __name__ == "__main__":
    main()
