def expected_races(c, m, p, v, memo=None):
    """Calculate expected number of races from state (c, m, p)"""

    if memo is None:
        memo = {}

    # If any item is invalid (<= 1e-9), check if pink is still valid
    if c <= 1e-9:
        if m <= 1e-9:
            # Both cash and impound invalid, only pink left
            return 1.0  # Always draw pink
        else:
            # Only impound and pink valid
            # Expected = 1 + expected from new state
            if m <= v:
                # Impound becomes invalid, only pink left
                return 1 + 1.0  # Draw impound then draw pink
            else:
                # Impound probability reduces by v
                new_m = m - v
                new_p = p + v
                return 1 + expected_races(0, new_m, new_p, v, memo)
    elif m <= 1e-9:
        # Only cash and pink valid
        if c <= v:
            # Cash becomes invalid, only pink left
            return 1 + 1.0  # Draw cash then draw pink
        else:
            # Cash probability reduces by v
            new_c = c - v
            new_p = p + v
            return 1 + expected_races(new_c, 0, new_p, v, memo)

    # Check if we're in a terminal state (pink is invalid? we need pink, so if pink invalid, this should never happen)
    if p <= 1e-9:
        return float('inf')

    # If we're in a non-terminal state, use memoization
    key = (round(c, 12), round(m, 12), round(p, 12))

    if key in memo:
        return memo[key]

    # Calculate expected value
    expected = 0.0

    # Try drawing cash
    if c > 1e-9:
        if c <= v:
            # Cash becomes invalid, distribute v to remaining items (impound and pink)
            new_c = 0.0
            new_m = m + v / 2
            new_p = p + v / 2

            expected += c * (1 + expected_races(new_c, new_m, new_p, v, memo))
        else:
            # Cash probability reduces by v
            new_c = c - v
            new_m = m + v / 2
            new_p = p + v / 2

            expected += c * (1 + expected_races(new_c, new_m, new_p, v, memo))

    # Try drawing impound
    if m > 1e-9:
        if m <= v:
            # Impound becomes invalid, distribute v to remaining items (cash and pink)
            new_m = 0.0
            new_c = c + v / 2
            new_p = p + v / 2

            expected += m * (1 + expected_races(new_c, new_m, new_p, v, memo))
        else:
            # Impound probability reduces by v
            new_m = m - v
            new_c = c + v / 2
            new_p = p + v / 2

            expected += m * (1 + expected_races(new_c, new_m, new_p, v, memo))

    # Try drawing pink
    expected += p * 1.0  # Draw pink immediately

    memo[key] = expected
    return expected

