def solve():
    MOD = 998244353
    n = int(input())
    a = list(map(int, input().split()))

    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i - 1] * 2) % MOD

    ans = 0
    for i in range(1, n + 1):
        # sum_{k=1}^i a_k * 2^{n-i}
        # = a_i * 2^{n-i} + sum_{k=1}^{i-1} a_k * 2^{n-i}
        ans = (ans + a[i - 1] * pow2[n - i]) % MOD
        if i > 1:
            ans = (ans + a[i - 1] * pow2[n - i]) % MOD

    print(ans)

solve()
