def is_all_unique(row):
    """Check if all elements in a row are unique"""
    return len(set(row)) == 9

def solve_sudoku(input_grid):
    """Make the grid anti-sudoku"""
    # Convert to list of lists
    grid = [list(row) for row in input_grid]

    # Fix rows
    for i in range(9):
        if is_all_unique(grid[i]):
            # Change first element to duplicate the last element
            grid[i][0] = grid[i][-1]

    # Fix columns
    for j in range(9):
        if is_all_unique([grid[i][j] for i in range(9)]):
            # Change first element to duplicate the last element
            grid[0][j] = grid[-1][j]

    return grid

def main():
    import sys
    data = sys.stdin.read().split()
    t = int(data[0])
    idx = 1

    for _ in range(t):
        grid = []
        for _ in range(9):
            grid.append(data[idx])
            idx += 1

        result = solve_sudoku(grid)

        for row in result:
            print(row)

if __name__ == "__main__":
    main()
