            K = int(parts[2])
            level = X.bit_length() - 1
            size = 1 << level

            # Value at position p is shifted by K
            val_perm[level] = {}
            for p in range(size):
                val = 2**level + p
                val_perm[level][(val, p)] = (val - K) % size
        elif T == 2:
