    sorted_pos = {val: i + 1 for i, val in enumerate(sorted_a)}

    # Sort the elements by their position in the original sequence
    elements = [(val, pos[val], sorted_pos[val]) for val in a]

    # Find the maximum number of subsequences (length of longest decreasing subsequence)
    # We'll use patience sorting for LIS
    piles = []
    for val, orig_pos, sorted_pos in elements:
        # Find the rightmost pile where the top element's sorted position is > current's sorted position
        left, right = 0, len(piles)
        while left < right:
            mid = (left + right) // 2
            if piles[mid][-1][1] > sorted_pos:
                right = mid
            else:
                left = mid + 1

