from collections import defaultdict

def solve():
    # Read the first line
    line = input().strip()
    if not line:
        n = 0
    else:
        n = int(line)

    # Read the array line
    while True:
        try:
            data = list(map(int, input().split()))
            break
        except:
            # If we get EOF, maybe we just have the array
            # Let's try reading again
            pass

    if len(data) == 0:
        # Handle case with no array
        n = 0
    else:
        # Try to determine k
        if n == 1:
            # Single number means both n and k
            k = data[0]
        else:
            k = data[1]  # k is the second element
        a = data

    # Use two pointers and Counter to find the longest k-good segment
    left = 0
    max_len = 0
    counts = defaultdict(int)

    for right in range(n):
        counts[a[right]] += 1

        # If window contains more than k different values, shrink from the left
        while len(counts) > k:
            counts[a[left]] -= 1
            if counts[a[left]] == 0:
                del counts[a[left]]
            left += 1

        # Update maximum length
        current_len = right - left + 1
        if current_len > max_len:
            max_len = current_len
            # Store the indices (1-indexed)
            result_left = left + 1
            result_right = right + 1

    print(max_len)
    print(result_left, result_right)

if __name__ == "__main__":
    solve()
