import sys

def solve_rebus(rebus):
    # Parse the rebus
    parts = rebus.split()
    if len(parts) < 5:
        return "Impossible"

    # Extract n from the last part
    try:
        n = int(parts[-1])
    except ValueError:
        return "Impossible"

    # Check if the format matches
    if parts[0] != "?" or parts[2] != "-" or parts[4] != "+" or parts[5] != "=":
        return "Impossible"

    # Extract the positions of the question marks
    # Format: ? + ? - ? + ? = n
    # So we need 4 question marks
    if len([part for part in parts if part == "?"]) != 4:
        return "Impossible"

    # Try to find a solution
    for c in range(1, n + 1):
        for a in range(1, n + 1):
            for b in range(1, n + 1):
                # Compute d
                d = n + c - a - b
                if 1 <= d <= n:
                    # Found a solution!
                    return f"Possible\n{a} + {b} - {c} + {d} = {n}"

    return "Impossible"

