def find_max_ones_number(l, r):
    """Find the number in [l, r] with the maximum number of '1' bits.
    If there are ties, return the smallest one."""

    # Try from largest bit count to smallest
    k = r.bit_length()

    # Check if there's any overlap with numbers that have k bits set
    start = (1 << (k-1))
    end = (1 << k) - 1

    if l <= end and start <= r:
        # Return the smallest number in the overlap
        return max(l, start)

    # If no overlap, try with k-1 bits set
    for bit_count in range(k-1, 0, -1):
        start = (1 << (bit_count-1))
        end = (1 << bit_count) - 1

        if l <= end and start <= r:
            return max(l, start)

    # If no numbers with bits set work, return l (which has 0 bits set)
    return l

