import sys
from collections import defaultdict

def main():
    line = sys.stdin.readline()
    if not line:
        return

    n, k = map(int, line.split())

    a = list(map(int, sys.stdin.readline().split()))

    freq = defaultdict(int)
    distinct = 0
    max_len = 0
    best_l = 0

    l = 0
    for r in range(n):
        if freq[a[r]] == 0:
            distinct += 1
        freq[a[r]] += 1

        while distinct > k:
            freq[a[l]] -= 1
            if freq[a[l]] == 0:
                distinct -= 1
            l += 1

        if r - l + 1 > max_len:
            max_len = r - l + 1
            best_l = l

    print(best_l + 1, best_l + max_len)

if __name__ == "__main__":
    main()
