n = int(input())
segments = []
for _ in range(n):
    l, r = map(int, input().split())
    segments.append((l, r))

# Sort segments by left endpoint
segments.sort()

# DSU implementation
tree_parent = list(range(n))
tree_rank = [1] * n

def find(u):
    """Find the root of u with path compression"""
    while tree_parent[u] != u:
        tree_parent[u] = tree_parent[tree_parent[u]]
        u = tree_parent[u]
    return u

def union(u, v):
    """Union the sets containing u and v"""
    u_root = find(u)
    v_root = find(v)
    if u_root == v_root:
        return False
    # Union by rank
    if tree_rank[u_root] < tree_rank[v_root]:
        tree_parent[u_root] = v_root
    else:
        tree_parent[v_root] = u_root
        if tree_rank[u_root] == tree_rank[v_root]:
            tree_rank[u_root] += 1
    return True

edges = 0
# Count edges and connect components
for i in range(n):
    l1, r1 = segments[i]
    for j in range(i + 1, n):
        l2, r2 = segments[j]
        # Check if segments intersect
        if l1 < r2 and l2 < r1:
            # Check if neither is completely inside the other
            if not (l1 >= l2 and r1 <= r2) and not (l2 >= l1 and r2 <= r1):
                edges += 1
                union(i, j)

# Check if it's a tree: connected and exactly n-1 edges
if edges == n - 1 and all(find(i) == find(0) for i in range(n)):
    print("YES")
else:
    print("NO")
