def find_substrings(s, target):
    indices = []
    for i in range(len(s) - 1):
        if s[i:i+2] == target:
            indices.append(i)
    return indices

s = input().strip()
ab_indices = find_substrings(s, "AB")
ba_indices = find_substrings(s, "BA")

